CREATE TABLE IF NOT EXISTS profiles(id TEXT PRIMARY KEY,name TEXT NOT NULL,team TEXT NOT NULL DEFAULT '',created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bots(id TEXT PRIMARY KEY,owner TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL,code TEXT NOT NULL,hash TEXT NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL,created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS bots_owner ON bots(owner);
CREATE TABLE IF NOT EXISTS matches(id TEXT PRIMARY KEY,owner TEXT NOT NULL,bot_id TEXT,opponent TEXT NOT NULL,name TEXT NOT NULL,replay TEXT NOT NULL,kind TEXT NOT NULL,created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS matches_owner ON matches(owner);
CREATE TABLE IF NOT EXISTS tournaments(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL,deadline TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS registrations(id TEXT PRIMARY KEY,owner TEXT NOT NULL,tournament_id TEXT NOT NULL,bot_id TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,owner TEXT NOT NULL,action TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rooms(id TEXT PRIMARY KEY,host_id TEXT NOT NULL,host_name TEXT NOT NULL,guest_id TEXT,guest_name TEXT,moves TEXT NOT NULL,revision INTEGER NOT NULL,status TEXT NOT NULL,winner TEXT,reason TEXT,created TEXT NOT NULL,expires TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS rooms_host ON rooms(host_id);
CREATE TABLE IF NOT EXISTS auth_users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,salt TEXT NOT NULL,password_hash TEXT NOT NULL,is_admin INTEGER NOT NULL DEFAULT 0,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE,expires BIGINT NOT NULL,created BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS auth_sessions_user ON auth_sessions(user_id);
CREATE TABLE IF NOT EXISTS auth_attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires BIGINT NOT NULL);
ALTER TABLE auth_users ADD COLUMN IF NOT EXISTS verified BIGINT NOT NULL DEFAULT 0;
ALTER TABLE auth_users ADD COLUMN IF NOT EXISTS disabled INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS auth_tokens(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE,kind TEXT NOT NULL,expires BIGINT NOT NULL,created BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS auth_tokens_owner ON auth_tokens(user_id,kind);
